'use strict';

// Illustrative reviews for the portfolio, not reviews submitted by real customers.
// The native MockReview shape provides the author/rating/dish/text hierarchy.
window.wansoReviews = (() => {
  const people = [
    ['小禾', '禾'], ['阿越', '越'], ['小满', '满'], ['安安', '安'],
    ['木木', '木'], ['小林', '林'], ['阿青', '青'], ['小圆', '圆'],
    ['北北', '北'], ['小夏', '夏'], ['米粒', '米'], ['阿宁', '宁']
  ];
  // The three entries refer to the first three actual dishes in each fixture menu.
  const stories = {
    pho: [
      [d => `🍜 ${d}的汤味比较清爽，先喝一口原汤，再挤青柠，鸡肉和米香都更明显。辣椒另放比较适合我，喜欢浓重口味的话可以再自己加。`, ['汤底清爽', '辣椒另放']],
      [d => `午餐选了${d}。鸡肉撕开后拌进粉里，比只吃几块肉更容易每口都有搭配。我的饭量偏大，会再加一份蔬菜；汤粉最好拆开就吃，放久了口感会变软。`, ['工作午餐', '建议及时食用']],
      [d => `${d}适合想吃热食、又不想要太多酱汁的时候。鸡胸肉比较有嚼劲，先拌一点汤再吃更合适；如果更喜欢嫩一点的口感，我会换成鸡腿款。`, ['口味偏清淡', '按口感选肉']]
    ],
    mixed: [
      [d => `🥢 ${d}最吸引我的是酸甜酱汁配鸡肉的组合。我先加半份酱，拌匀后再调整，比一次全部倒进去更好控制味道，香草也可以最后再放。`, ['酱汁分次加', '干拌口感']],
      [d => `不想喝汤时会选${d}，鸡腿肉和拌粉比较搭。单吃粉会觉得味道淡，要把酱汁拌开；花生或鱼露有忌口的话，点之前还是要问清配料。`, ['鸡腿搭配', '注意配料']],
      [d => `${d}的鸡胸肉偏扎实，适合我这种喜欢多嚼几口的人。酱汁有自己的酸甜味，不是白水煮鸡的口味；下次会备注少酱，再加一份小配菜。`, ['肉质扎实', '可备注少酱']]
    ],
    rice: [
      [d => `🍚 ${d}把米饭、鸡肉和配菜配在一起，工作间隙不用再凑一整餐。我喜欢先吃原味，再蘸一点酱；如果平时蔬菜吃得多，建议另外加份青菜。`, ['一人食搭配', '酱料分开']],
      [d => `选${d}是因为鸡肉比较容易和米饭拌匀，每口都能吃到。整体更像家常午餐，不是浓油赤酱那一类；饭量很大的话，可以先看看加饭的价格。`, ['家常午餐', '可按饭量加配']],
      [d => `${d}的烤香味更突出，比白切款更适合我想吃有味道的一餐。酱汁已经够配饭了，我不会再全部倒进去；偏清淡的人可以先看看同店白切鸡的选择。`, ['烤香风味', '按口味选择']]
    ],
    banh: [
      [d => `🥖 ${d}很适合不想坐下来吃整份饭的早晨。鸡肉配黄瓜和酸菜，咬起来有层次；法棍最好尽快吃，包着放太久会少一点酥脆感。`, ['方便携带', '趁早吃更合适']],
      [d => `${d}的烤鸡香味比较明显，配上酸菜没那么腻。我喜欢不加辣椒，但会保留一点酸菜；如果不习惯酸味，备注时最好把这两项分开说。`, ['烤鸡夹馅', '备注写具体']],
      [d => `早餐换成${d}，鸡蛋的口感比肉馅柔和，配杯饮品刚好。把它当一顿完整午餐，对我来说会偏轻，食量大一点可以再加份小食。`, ['轻量早餐', '按食量加配']]
    ],
    veggie: [
      [d => `🥬 ${d}里豆腐和蔬菜的口感有变化，想换一顿植物食材为主的午餐时会考虑。炒饭还是有调味的，喜欢清淡可以备注少油；严格素食要另外确认酱料。`, ['植物食材', '调味需确认']],
      [d => `${d}的香菇味道比较突出，和蔬菜搭着吃不单调。它适合想多吃蔬菜的一餐，不过我的饭量偏大，会再加一份豆腐，让搭配更完整。`, ['香菇风味', '可加份豆腐']],
      [d => `${d}的番茄酸甜味更适合拌饭，豆腐也比较容易入口。我会先试酱汁再拌，不喜欢酸甜口的话可以换时蔬款；饮食有禁忌仍需和店家确认。`, ['番茄酸甜', '有不同口味可选']]
    ],
    coffee: [
      [d => `☕ ${d}适合下午想喝点咖啡、又想配一口小食的时候。小面包和咖啡交替吃比较舒服；炼乳的甜感明显，我更喜欢先少加一点，再按口味调整。`, ['咖啡配小食', '甜度可备注']],
      [d => `${d}能更直接地喝到咖啡本身的苦香，适合我不想喝奶咖的时候。它不是甜口饮料，第一次尝试可以配块面包；冰融化后味道会变淡，我不会放太久。`, ['黑咖啡风味', '适合配小食']],
      [d => `${d}的奶香和咖啡味比较容易接受，搅匀后再喝更均衡。对我来说常规甜度稍高，会备注少炼乳；需要避免乳制品的人应先确认配料或换别的饮品。`, ['先搅拌再喝', '留意含乳配料']]
    ],
    tea: [
      [d => `🍋 ${d}是我下午休息时会选的搭配，柠檬的清爽味配小饼干不单调。我更喜欢少糖，先喝茶再吃饼干；如果是正餐时间，这份组合还不太够。`, ['下午茶搭配', '少糖更合口味']],
      [d => `${d}能喝到柠檬的酸香，想喝得清爽一点会选它。少糖并不等于没有甜味，我会先从半糖试起；胃口不适合酸味的时候，会换更温和的饮品。`, ['柠檬酸香', '按口味调甜度']],
      [d => `${d}比柠檬款更偏果香，适合想换个口味的下午。我会选少冰，慢慢喝也不容易一下变淡；偏好明显茶味的人，点之前可以再问一下茶底。`, ['果香茶饮', '可备注冰量']]
    ],
    bun: [
      [d => `🍲 ${d}的米线比河粉更细，香菇和鸡肉搭在汤里，适合想换一种热汤主食的时候。香草我习惯最后再放；喜欢有嚼劲的口感，记得拆开后及时吃。`, ['细米线口感', '香草最后加']],
      [d => `${d}更适合我想吃一点肉感的午餐，鸡腿和细米线搭着吃比较舒服。我会先尝汤再加调料，避免把汤味盖住；饭量大可以另外加菜，不必先把辣椒全倒进去。`, ['鸡腿搭配', '先尝汤再调味']],
      [d => `${d}的鸡胸肉比鸡腿款更扎实，和清汤搭配比较简单。想要更丰富的口感，可以加份香菇；如果更在意肉的柔嫩程度，我会选同店鸡腿款。`, ['清汤搭配', '口感各有侧重']]
    ]
  };
  const archivedExamples={
    moc:[
      ['Phở gà đùi','鸡腿汤河粉','🍜 鸡腿汤河粉比较适合想吃热汤的一餐。我的习惯是先尝原汤，再放一点青柠和辣椒，不会一次把调料都加进去。喜欢有肉感的人可以选鸡腿，香菜有忌口记得提前备注。'],
      ['Phở trộn gà đùi','鸡腿拌河粉','不想喝汤时会考虑鸡腿拌河粉，拌匀以后粉和鸡肉更容易一起吃到。酱汁有酸甜味，我会先加一半；如果平时吃得比较清淡，备注少酱比只写“清淡”更明确。'],
      ['Cháo gà thường','鸡肉粥','鸡肉粥适合想吃软一点、口味简单一点的时候。作为轻量的一餐很方便，食量大的人可以再看看小食。我会等粥稍凉再加调味，不把热食的第一口当作最终咸淡判断。']
    ],
    quyen:[
      ['Phở gà đùi nước','鸡腿汤河粉','🍜 鸡腿汤河粉是我在这份菜单里会先考虑的热食。鸡肉和粉交替吃比较有层次，调料先分开放更容易调整；汤粉放久了会变软，拿到后尽早吃更合适。'],
      ['Bún gà nước','鸡肉汤米线','想换一种主食口感时会选鸡肉汤米线。细米线和河粉的感觉不一样，我更喜欢先喝汤，再拌入香草；如果期待更有嚼劲的面条，可以对照菜单里的其他主食再选。'],
      ['Nộm gà','凉拌鸡肉','凉拌鸡肉适合与热汤主食搭着吃，酸甜味能换一下口感。它更像配菜，我不会直接把它当成完整的一餐；花生、鱼露或香草有忌口时，需要先向店家确认。']
    ]
  };
  function forStore(value) {
    const archiveId=typeof value==='string'?value:value?.id;
    const archive=archivedExamples[archiveId];
    if(archive)return archive.map(([dishName,dish,text],index)=>({id:archiveId+'-review-'+index,name:people[index*3][0],initial:people[index*3][1],rating:index===1?5:4,platform:archiveId==='moc'&&index===1?'shopee':'grab',platformLabel:archiveId==='moc'&&index===1?'ShopeeFood':'GrabFood',dish: dish+' · '+dishName,text,tags:[],sample:true}));
    const store = typeof value === 'string'
      ? window.wansoCatalog?.find(item => item.id === value)
      : value;
    if (!store || !stories[store.key]) return [];
    const seed = [...store.id].reduce((sum, char) => sum + char.charCodeAt(0), 0);
    return stories[store.key].map(([story, tags], index) => {
      const menuItem = store.menu?.[index];
      const dish = menuItem?.translations?.zh || menuItem?.name?.split(' · ')[1] || store.dishZh;
      const [name, initial] = people[(seed + index * 3) % people.length];
      const platform = (seed + index) % 2 ? 'grab' : 'shopee';
      return {
        id:store.id + '-review-' + (index + 1), name, initial, rating:index === 1 ? 5 : 4,
        platform, platformLabel:platform === 'grab' ? 'GrabFood' : 'ShopeeFood', dish,
        text:story(dish), tags:[...tags], sample:true
      };
    });
  }
  return {forStore, label:'评论示例'};
})();
